INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass nicht funktionale Anforderungen immer die Hauptfunktionen eines Systems beschreiben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Beschreiben Eigenschaften"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich nicht funktionale Anforderungen für ein IT-System definiere?', 3, '[{"text": "Systemzuverlässigkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Schnellste Entwicklung", "correct": false, "because": "Qualität zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zu nicht funktionalen Anforderungen?', 5, '[{"text": "Leistung", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Sicherheit", "correct": true, "because": "Schützt Daten"}, {"text": "Datenbankgröße", "correct": false, "because": "Funktional"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nicht funktionale Anforderungen betreffen Systemeigenschaften. b) Sie definieren immer die Benutzeroberfläche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer UI"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich nicht funktionale Anforderungen für ein IT-System festlege?', 4, '[{"text": "Benutzbarkeit", "correct": false, "because": "Wichtige Eigenschaft"}, {"text": "Wartbarkeit", "correct": false, "because": "Beeinflusst Pflege"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Systemfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob nicht funktionale Anforderungen nur die Sicherheit betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Leistung, Usability"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit nicht funktionalen Anforderungen?', 3, '[{"text": "Systemqualität sichern", "correct": true, "because": "Verbessert Eigenschaften"}, {"text": "Schnellste Entwicklung", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Funktionen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu nicht funktionalen Anforderungen?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Bestimmt Wachstum"}, {"text": "Verfügbarkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Datenbankstruktur", "correct": false, "because": "Funktional"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Nicht funktionale Anforderungen betreffen die Benutzbarkeit. b) Sie sind immer optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um nicht funktionale Anforderungen zu definieren?', 4, '[{"text": "Leistungsmetriken", "correct": false, "because": "Bestimmen Geschwindigkeit"}, {"text": "Sicherheitsstandards", "correct": false, "because": "Schützen System"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Systemfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind nicht funktionale Anforderungen immer die Hauptfunktionen eines Systems?', 2, '[{"text": "Nein", "correct": true, "because": "Beschreiben Eigenschaften"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten nicht funktionale Anforderungen?', 4, '[{"text": "Verbesserte Sicherheit", "correct": true, "because": "Schützt Daten"}, {"text": "Höhere Benutzbarkeit", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass nicht funktionale Anforderungen nur für große Systeme gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um nicht funktionale Anforderungen effektiv zu definieren?', 3, '[{"text": "Leistungskriterien", "correct": true, "because": "Bestimmen Qualität"}, {"text": "Günstigste Lösung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nicht funktionale Anforderungen betreffen die Verfügbarkeit. b) Sie definieren immer die Datenstruktur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenstruktur funktional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei nicht funktionalen Anforderungen?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Beeinflusst Pflege"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich nicht funktionale Anforderungen festlege?', 3, '[{"text": "Skalierbarkeit", "correct": false, "because": "Bestimmt Wachstum"}, {"text": "Benutzbarkeit", "correct": false, "because": "Fördert Akzeptanz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Systemfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind nicht funktionale Anforderungen immer optional?', 3, '[{"text": "Nein", "correct": true, "because": "Wichtig für Qualität"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob nicht funktionale Anforderungen nur die Sicherheit betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Leistung, Usability"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für nicht funktionale Anforderungen?', 4, '[{"text": "Systemzuverlässigkeit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Schnellste Entwicklung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
